// Minimal Space Debris Dodger game
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 400;
  const H = canvas.height = canvas.clientHeight || 600;

  // ---- Game objects ----
  const ship = { x: W/2, y: H-30, w: 30, h: 15, speed: 4, health: 3 };
  const bullets = [];
  const debris = [];

  // ---- Input handling ----
  const keys = {};
  window.addEventListener('keydown', e => keys[e.code] = true);
  window.addEventListener('keyup', e => keys[e.code] = false);

  // ---- Helpers ----
  function rect(o) { return {x:o.x, y:o.y, w:o.w, h:o.h}; }
  function intersect(a,b) {
    return a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y;
  }

  // ---- Game loop ----
  let frames = 0;
  function loop(){
    // move ship
    if(keys['ArrowLeft']) ship.x = Math.max(0, ship.x - ship.speed);
    if(keys['ArrowRight']) ship.x = Math.min(W-ship.w, ship.x + ship.speed);
    if(keys['Space']) {
      // fire rate limit
      if(frames % 10 === 0) bullets.push({x: ship.x+ship.w/2-2, y: ship.y, w:4, h:10, speed:6});
    }
    // update bullets
    for(let i=bullets.length-1;i>=0;i--){
      const b=bullets[i];
      b.y -= b.speed;
      if(b.y < -b.h) bullets.splice(i,1);
    }
    // spawn debris
    if(frames % Math.max(30, 120 - ship.health*20) === 0) {
      const size = 20 + Math.random()*15;
      debris.push({x: Math.random()*(W-size), y: -size, w:size, h:size, speed:2+Math.random()*2});
    }
    // update debris
    for(let i=debris.length-1;i>=0;i--){
      const d=debris[i];
      d.y += d.speed;
      // collision with ship
      if(intersect(rect(d), rect(ship))) { ship.health--; debris.splice(i,1); }
      // collision with bullets
      for(let j=bullets.length-1;j>=0;j--){
        if(intersect(rect(d), rect(bullets[j]))) { debris.splice(i,1); bullets.splice(j,1); break; }
      }
      // remove off‑screen
      if(d.y>H) debris.splice(i,1);
    }
    // draw
    ctx.clearRect(0,0,W,H);
    // ship
    ctx.fillStyle='white';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // bullets
    ctx.fillStyle='lime';
    bullets.forEach(b=>ctx.fillRect(b.x,b.y,b.w,b.h));
    // debris
    ctx.fillStyle='red';
    debris.forEach(d=>ctx.fillRect(d.x,d.y,d.w,d.h));
    // health
    ctx.fillStyle='yellow';
    ctx.font='16px monospace';
    ctx.fillText('Health: '+ship.health,10,20);

    if(ship.health>0) {
      frames++;
      requestAnimationFrame(loop);
    } else {
      ctx.fillStyle='white';
      ctx.textAlign='center';
      ctx.fillText('Game Over', W/2, H/2);
    }
  }
  requestAnimationFrame(loop);
})();
